/* Original Hebrew teaching material and tasks, integrated with the local lab. */
const lessons=[
{id:'board',title:'הלוח כנקודת התחלה',topic:'היכרות',minutes:4,kind:'lab',intro:'מיקרו־בקר מריץ הוראות, קורא כניסות ומשנה יציאות. הלוח שסביבו מוסיף הזנה, מחברים ורכיבים שמאפשרים לנו לעבוד איתו בנוחות.',why:'הפרדה בין מתח הזנה, אות לוגי ואדמה מונעת הרבה טעויות. פין GPIO הוא קו אות; הוא אינו ספק כוח למנוע.',goals:['זהו חיבור GND ויציאה דיגיטלית.','הבדילו בין שם לוגי לבין מספר רגל פיזית.'],steps:['פתחו את הניסוי המוכן.','בחרו בלוח והיכנסו לחלונית ההדקים.','מצאו D2, ‏5V ו־GND.'],preset:'blink',task:'הוסיפו לוח Arduino UNO ופתחו את הקוד שלו.',check:()=>nodes.some(n=>n.type==='arduino_0')&&!$('codepanel').hidden,question:'איזה חיבור יוצר נקודת ייחוס משותפת בין הלוח לחיישן?',answers:['GND','כל פין PWM','מחבר USB בלבד'],correct:0,explain:'מתחים נמדדים ביחס לנקודת ייחוס. לוח וחיישן המחוברים יחד זקוקים בדרך כלל לאדמה משותפת.'},
{id:'ohm',title:'נגד, מתח וזרם',topic:'יסודות',minutes:6,kind:'lab',intro:'נגד קובע כמה זרם יעבור עבור מפל מתח נתון. חוק אוהם מקשר בין שלוש הגדולות: V = I × R.',why:'במעגל עם מקור של 5V ו־LED בעל מפל של 2V, הנגד נושא 3V. נגד של 1kΩ ייתן כ־3mA במודל האידאלי.',goals:['חשבו את המתח על הנגד.','המירו mA לאמפר לפני שימוש בנוסחה.'],steps:['פתחו את המעגל.','שנו את הנגד ל־1000Ω.','הריצו קוד ובדקו את הזרם במצב HIGH.'],preset:'blink',task:'שנו את הנגד ל־1kΩ והריצו עד שנמדד זרם חיובי.',check:()=>nodes.some(n=>n.type==='resistor'&&n.value===1000)&&recentSignal(s=>s.i>2.8&&s.i<3.2),question:'כמה זרם יזרום דרך 1kΩ כשנופלים עליו 3V?',answers:['3A','3mA','300mA'],correct:1,explain:'3V / 1000Ω = 0.003A = 3mA.'},
{id:'led',title:'אור עם גבול לזרם',topic:'יסודות',minutes:5,kind:'lab',intro:'LED הוא רכיב מקוטב: הולכה בכיוון הקדמי יוצרת אור. הזרם צריך לעבור דרך נגד טורי לפני שהוא חוזר לאדמה.',why:'מקור מתח אינו מגביל את הזרם בעצמו במודל הזה. נגד טורי מאפשר לבחור זרם מתאים במקום להסתמך על מאפייני LED לא ידועים.',goals:['זהו אנודה וקתודה.','בדקו שהנגד נמצא במסלול הזרם.'],steps:['פתחו את המעגל.','עקבו אחרי D2 → נגד → A של ה־LED.','מצאו את חיבור K → GND והריצו.'],preset:'blink',task:'הריצו את הקוד עד שמופיע זרם חיובי ב־LED.',check:()=>nodes.some(n=>n.type==='led')&&recentSignal(s=>s.i>0),question:'למה מוסיפים נגד בטור ל־LED?',answers:['כדי להפוך אותו לחיישן','כדי להגדיל את מתח המקור','כדי להגביל זרם'],correct:2,explain:'הנגד מגביל את הזרם. ערכו נקבע מהמתח שנופל עליו ומהזרם הרצוי.'},
{id:'timing',title:'זמן הופך לאות',topic:'קוד',minutes:6,kind:'lab',intro:'פקודות digitalWrite משנות מצב לוגי. שילוב של מצב HIGH, השהיה, מצב LOW והשהיה נוספת יוצר אות מחזורי.',why:'האוסצילוסקופ מציג מתי כל מצב התרחש. שינוי delay משנה את רוחב המקטעים בגל, בלי לשנות את המתח הלוגי של הלוח.',goals:['קשרו בין שורת קוד למקטע בגל.','זהו מחזור שלם של HIGH ו־LOW.'],steps:['פתחו והריצו את דוגמת ההבהוב.','פתחו את כלי הגלים.','שנו את שתי ההשהיות ל־200ms והשוו.'],preset:'blink',task:'הריצו עד שנרשמו גם 0V וגם מתח חיובי.',check:()=>recentSignal(s=>s.v===0)&&recentSignal(s=>s.v>4),question:'אם HIGH נמשך 500ms ו־LOW נמשך 500ms, מה אורך המחזור?',answers:['שנייה אחת','חצי שנייה','חמש שניות'],correct:0,explain:'מחזור כולל את שני המצבים: 500 + 500 = 1000ms.'},
{id:'switch',title:'מסלול פתוח ומסלול סגור',topic:'חיווט',minutes:4,kind:'lab',intro:'מקור מתח יוצר הפרש פוטנציאלים, אך זרם זקוק למסלול רציף. מפסק מאפשר לנו לקטוע את המסלול או להשלים אותו.',why:'במפסק אידאלי פתוח אין זרם. מפסק סגור אינו מוסיף התנגדות. במציאות קיימים גם התנגדות מגע וקפיצות מכניות.',goals:['עקבו אחרי לולאה שלמה.','קשרו בין מצב מפסק למדידה.'],steps:['פתחו את מעגל המנוע.','הפעילו את הסימולציה.','בחרו במפסק ופתחו אותו.'],preset:'motor',task:'פתחו את המפסק והריצו את הסימולציה.',check:()=>running&&nodes.some(n=>n.type==='switch'&&!n.value)&&lastSim.current===0,question:'מה קורה לזרם בלולאה כשהמפסק הטורי פתוח?',answers:['מוכפל','יורד לאפס','הופך למתח'],correct:1,explain:'פתיחת המסלול מפסיקה זרם במודל DC הטורי.'},
{id:'input',title:'לחצן שמחליט אם להאיר',topic:'קוד',minutes:8,kind:'lab',intro:'כניסה דיגיטלית מתארת מצב לוגי. אפשר לקרוא את המצב ולהשתמש בתנאי if כדי לבחור איזו יציאה לשנות.',why:'חיווט וקוד עובדים יחד: יש לחבר מתח ואדמה למודל הלחצן, ולהגדיר את פין הקריאה כ־INPUT ואת פין ה־LED כ־OUTPUT.',goals:['קראו digitalRead.','כתבו תנאי שמפריד בין שני מצבים.'],steps:['פתחו את דוגמת הלחצן.','הריצו את הקוד.','בחרו בלחצן ושנו את הקלט בין 0 ל־1.'],preset:'button',task:'הריצו ובדקו שה־LED נדלק כאשר קלט הלחצן הוא 1.',check:()=>nodes.some(n=>n.type==='button'&&n.value===1)&&recentSignal(s=>s.i>0),question:'איזו הגדרה מתאימה לפין שמקבל אות מלחצן?',answers:['OUTPUT','GND','INPUT'],correct:2,explain:'INPUT מאפשר קריאה של אות לוגי. במעגל פיזי לחצן חשוף דורש גם הגדרת משיכה מתאימה.'},
{id:'analog',title:'יותר משני מצבים',topic:'חיישנים',minutes:6,kind:'lab',intro:'קריאה אנלוגית מייצגת טווח ערכים. במעבדה זו הקלט מנורמל ל־0 עד 1023, כדי להמחיש מדידה רציפה.',why:'זהו מודל לימודי. מספר סיביות ה־ADC, מתח הייחוס והטווח בפועל תלויים בלוח ובתצורתו.',goals:['זהו מתח, אדמה ואות.','השוו בין מיקום הפוטנציומטר לקריאה.'],steps:['פתחו את דוגמת הפוטנציומטר.','הריצו ופתחו Serial Monitor.','שנו את המיקום מ־0% ל־100%.'],preset:'analog',task:'הריצו את דוגמת הקריאה עם פוטנציומטר מחובר.',check:()=>running&&nodes.some(n=>n.type==='pot')&&program&&board()?.code?.includes('analogRead'),question:'מה מייצג הערך 512 בטווח 0–1023?',answers:['בערך חצי מהטווח','מתח של 512V','שגיאה בחיישן'],correct:0,explain:'512 נמצא בקירוב באמצע טווח הקריאה. המרה למתח דורשת לדעת את מתח הייחוס.'},
{id:'pwm',title:'שינוי עוצמה עם PWM',topic:'קוד',minutes:8,kind:'lab',intro:'PWM משנה את החלק היחסי של הזמן שבו היציאה פעילה. יחס זה נקרא Duty Cycle. הוא אינו הופך פין דיגיטלי למקור מתח אנלוגי מושלם.',why:'המנוע הלימודי מציג מתח ממוצע עבור PWM. לכן הגל כאן לא מציג את הפולסים המהירים של חומרה אמיתית.',goals:['המירו קלט 0–1023 לפלט 0–255.','הבחינו בין ממוצע לבין פולסים.'],steps:['פתחו את ניסוי העוצמה.','הריצו.','שנו את הפוטנציומטר והשוו את הזרם.'],preset:'pwm',task:'הריצו קוד analogWrite וקבעו את הפוטנציומטר מעל 75%.',check:()=>running&&nodes.some(n=>n.type==='pot'&&n.value>75)&&board()?.code?.includes('analogWrite')&&recentSignal(s=>s.i>0),question:'מה מתאר Duty Cycle של 25%?',answers:['25V בכל זמן','רבע מהמחזור במצב פעיל','תדר של 25Hz תמיד'],correct:1,explain:'Duty Cycle מתאר יחס זמנים במחזור. התדר הוא נתון נפרד.'},
{id:'serial',title:'נותנים לקוד להסביר את עצמו',topic:'דיבוג',minutes:5,kind:'lab',intro:'הדפסה ל־Serial Monitor עוזרת להבין מה הקוד קרא ובאיזה שלב הוא נמצא. היא שימושית במיוחד כשפלט חזותי לבדו אינו מסביר את הבעיה.',why:'הדפיסו את המדידה לפני ההמרה וגם אחריה. כך אפשר להבחין בין בעיה בחיווט לבעיה בחישוב.',goals:['פתחו ערוץ Serial.','הדפיסו תווית וערך קריא.'],steps:['פתחו את הפוטנציומטר.','הריצו ושנו את הערך.','בדקו שהמספרים במוניטור משתנים.'],preset:'analog',task:'הפעילו Serial והציגו מדידה מהמכשיר המדומה.',check:()=>running&&!!$('console')&&/\d{2,4}/.test($('console').textContent),question:'איזה מידע שימושי להדפיס בעת בדיקת חיישן?',answers:['רק את שם הפרויקט','את צבע החוט בלבד','את הערך שנקרא ואת יחידת המדידה'],correct:2,explain:'ערך מדוד עם תווית ויחידה מסייע לזהות טעויות ולפרש את המצב.'},
{id:'light',title:'אור משנה התנגדות',topic:'חיישנים',minutes:5,kind:'lab',intro:'LDR הוא נגד שמשנה את התנגדותו לפי התאורה. המודל כאן ממפה חושך להתנגדות גבוהה ואור להתנגדות נמוכה.',why:'במעגל הטורי, שינוי התנגדות ה־LDR משנה את הזרם ב־LED. המיפוי המדויק תלוי בחיישן ובתאורה; כאן זהו קירוב בלבד.',goals:['השוו בין תאורה לזרם.','הבחינו בין מודל לבין עקומת יצרן.'],steps:['פתחו את מעגל האור.','הריצו את הסימולציה.','שנו את התאורה ל־100%.'],preset:'light',task:'קבעו תאורה מלאה והפעילו את המעגל.',check:()=>running&&nodes.some(n=>n.type==='ldr'&&n.value===100)&&lastSim.current>0,question:'כיצד משתנה התנגדות LDR טיפוסי כשיש יותר אור?',answers:['קטנה','תמיד אפס','גדלה תמיד'],correct:0,explain:'ב־LDR טיפוסי ההתנגדות יורדת עם עלייה בתאורה. הטווח והקצב תלויים ברכיב.'},
{id:'power',title:'מנוע דורש שלב הספק',topic:'מפעילים',minutes:7,kind:'reading',intro:'מנוע דורש זרם שעלול להיות גבוה בהרבה ממה שפין לוגי יכול לספק. דרייבר מתאים מפריד בין אות הבקרה לבין נתיב ההספק.',why:'במעגל פיזי משתמשים בדרייבר או טרנזיסטור מתאימים, דואגים להגנת מתח חוזר ומוודאים שהספק מסוגל לספק זרם התנעה.',goals:['הבדילו בין כניסת בקרה ליציאת מנוע.','זהו צורך במקור כוח מתאים.'],steps:['הוסיפו מנוע ובקר L293D מהספרייה.','קראו את תיאור ההדקים.','שרטטו לעצמכם נתיב אות ונתיב הספק נפרדים.'],task:'תרגיל ידע: הסבירו לעצמכם מדוע GPIO אינו מזין מנוע ישירות.',question:'מה תפקיד דרייבר מנוע?',answers:['להחליף כל חיישן','לאפשר לאות בקרה קטן לשלוט בנתיב הספק','להפוך זרם ישר לאדמה'],correct:1,explain:'הדרייבר מקבל אותות בקרה וממתג את הזרם שהמנוע צריך. L293D אינו מדומה חשמלית בגרסה זו.'},
{id:'capacitor',title:'אנרגיה בשדה חשמלי',topic:'יסודות',minutes:6,kind:'reading',intro:'קבל אוגר מטען לפי Q = C × V. האנרגיה האגורה תלויה בקיבול ובריבוע המתח: E = ½CV².',why:'בקבל אלקטרוליטי יש גם קוטביות ומתח עבודה מרבי. במצב DC יציב קבל אידאלי אינו מעביר זרם; טעינה ופריקה דורשות מודל תלוי זמן.',goals:['המירו μF לפאראד.','הבחינו בין מצב יציב לתהליך טעינה.'],steps:['הוסיפו קבל ובחרו קיבול.','בדקו את סימוני הקוטביות.','קראו מדוע מודל DC מציג אותו כנתק.'],task:'תרגיל ידע: חשבו מה יקרה לאנרגיה אם המתח מוכפל.',question:'כאשר הקיבול קבוע והמתח מוכפל, האנרגיה האגורה…',answers:['מוכפלת פי 2','לא משתנה','מוכפלת פי 4'],correct:2,explain:'האנרגיה תלויה ב־V². הכפלת המתח מגדילה אותה פי ארבעה.'},
{id:'protocols',title:'חוטים שמדברים בפרוטוקול',topic:'תקשורת',minutes:7,kind:'reading',intro:'חיישנים דיגיטליים רבים שולחים מידע דרך פרוטוקול. חיבור חוטים לבדו אינו מספיק: דרושים גם תזמון, כתובת, פקודות ולעיתים ספרייה מתאימה.',why:'I²C משתמש בדרך כלל בקווי SDA ו־SCL משותפים. יש לוודא מתחי לוגיקה, נגדי משיכה וכתובת חיישן לפי המודול.',goals:['זהו קווי נתונים ושעון.','הבינו למה דרוש מודל פרוטוקול.'],steps:['בחרו מודול MPU6050 או מסך OLED.','חפשו את ההדקים SDA ו־SCL.','בדקו את רמת התמיכה המוצגת ברכיב.'],task:'תרגיל ידע: זהו למה רכיב יכול להופיע במשטח ועדיין לא להחזיר נתונים.',question:'איזה זוג שמות נפוץ באפיק I²C?',answers:['SDA ו־SCL','A ו־K','COM ו־NO'],correct:0,explain:'SDA הוא נתונים ו־SCL הוא שעון. הפרוטוקול עדיין אינו מדומה עבור המודולים האלה במעבדה.'},
{id:'scope',title:'קוראים גל ולא מנחשים',topic:'מדידה',minutes:6,kind:'lab',intro:'גרף מתח מול זמן עוזר לזהות את גובה האות, משכו והמחזוריות שלו. בחירת בסיס זמן מתאים חשובה לא פחות מהמדידה עצמה.',why:'קו ישר יכול להיות אות DC תקין. גל הדגמה הוא כלי ללימוד הקריאה, והוא מסומן בנפרד מאות שמקורו במעגל.',goals:['בחרו בסיס זמן ומתח לחלוקה.','הקפיאו גל כדי לבדוק אותו.'],steps:['פתחו והריצו הבהוב.','עברו למצב מדידה.','הקפיאו את הגל לאחר שני מצבים.'],preset:'blink',task:'הציגו את הגל והקפיאו אחרי HIGH ו־LOW.',check:()=>scopeFrozen&&recentSignal(s=>s.v>4)&&recentSignal(s=>s.v===0),question:'מה מתאר הציר האופקי באוסצילוסקופ הזה?',answers:['התנגדות','זמן','מספר רכיבים'],correct:1,explain:'הציר האופקי הוא זמן; הציר האנכי מציג מתח או זרם לפי הערוץ והקנה המידה.'},
{id:'debug',title:'מאתרים תקלה אחת בכל פעם',topic:'דיבוג',minutes:7,kind:'lab',intro:'בדיקה שיטתית מתחילה בהזנה ובאדמה, ממשיכה למסלול הזרם ואז עוברת לאותות ולקוד. שינוי של כמה דברים יחד מקשה להבין מה פתר את התקלה.',why:'השתמשו בסכמה, ברשימת החיבורים ובמדידות כדי לתאר את המעגל הקיים, ולא רק את מה שתכננתם לחבר.',goals:['קראו הודעת תקלה.','שחזרו מצב קודם דרך היסטוריית הפעולות.'],steps:['פתחו את ההבהוב.','מחקו חיבור וצפו בבדיקה.','החזירו אותו בעזרת ביטול פעולה.'],preset:'blink',task:'סיימו עם מעגל LED תקין לאחר בדיקת החיווט.',check:()=>nodes.some(n=>n.type==='led')&&recentSignal(s=>s.i>0),question:'מהו צעד ראשון טוב כשהמעגל לא מגיב?',answers:['להחליף את כל הקוד מיד','להוסיף מתח בלי לבדוק','לבדוק הזנה ואדמה ואז את החיבורים'],correct:2,explain:'מתח ואדמה הם תנאי בסיס. אחרי שהם תקינים אפשר לבודד את התקלה בהדרגה.'},
{id:'final',title:'פרויקט: כניסה, החלטה ופלט',topic:'פרויקט מסכם',minutes:12,kind:'lab',intro:'פרויקט שימושי מחבר שלושה שלבים: קריאת העולם, החלטה בקוד ופעולה. נבנה פלט אור שעוצמתו נקבעת על ידי קלט אנלוגי.',why:'הצלחה אינה רק אור שנדלק. חשוב גם להבין את החישוב, לבדוק קצוות ולשמור תיעוד שמאפשר לבנות את הפרויקט מחדש.',goals:['בדקו קלט מינימלי ומקסימלי.','ייצאו קוד, חיבורים ורשימת רכיבים.'],steps:['פתחו את ניסוי ה־PWM.','בדקו את שני קצות הפוטנציומטר.','תנו שם לפרויקט ושמרו אותו.'],preset:'pwm',task:'הריצו את הבקרה עם פוטנציומטר ונגד של לפחות 330Ω.',check:()=>running&&nodes.some(n=>n.type==='pot')&&nodes.some(n=>n.type==='resistor'&&n.value>=330)&&board()?.code?.includes('map(')&&recentSignal(s=>s.i>0),question:'מה כדאי לכלול בתיעוד הפרויקט?',answers:['קוד, ערכי רכיבים וחיבורים','רק צילום של ה־LED','רק שם הלוח'],correct:0,explain:'שלושת סוגי המידע מאפשרים להבין ולשחזר את הפרויקט. נתוני יצרן משלימים את התיעוד לבנייה פיזית.'}
];
let courseState={completed:[],answers:{},current:0};try{const saved=JSON.parse(localStorage.getItem('voltlab-course-v1')||'null');if(saved&&Array.isArray(saved.completed)&&saved.answers&&typeof saved.answers==='object'&&!Array.isArray(saved.answers)&&Number.isInteger(saved.current))courseState={completed:saved.completed.filter(id=>lessons.some(l=>l.id===id)),answers:saved.answers,current:Math.max(0,Math.min(15,saved.current))}}catch{}let courseTab='overview',lessonStart=performance.now(),practicePassed=false;function recentSignal(predicate){return scopeSamples.some(s=>s.t>=lessonStart&&!s.demo&&predicate(s))}function persistCourse(){try{localStorage.setItem('voltlab-course-v1',JSON.stringify(courseState))}catch{toast('לא ניתן לשמור התקדמות בדפדפן הזה')}}
const coursePanel=document.createElement('aside');coursePanel.className='coursepanel panel';document.querySelector('.workspace').before(coursePanel);const lessonStrip=document.createElement('section');lessonStrip.className='lessonstrip';document.querySelector('main').after(lessonStrip);
function startLesson(index){courseState.current=index;courseTab='overview';lessonStart=performance.now();practicePassed=false;persistCourse();renderCourse()}
function renderCourse(){const l=lessons[courseState.current],answer=courseState.answers[l.id],done=courseState.completed.includes(l.id);coursePanel.innerHTML=`<div class="courseheading"><span class="eyebrow">VOLT ACADEMY / מסלול יסודות</span><div><h2>מבינים דרך התנסות</h2><b>${courseState.completed.length}/${lessons.length}</b></div><progress value="${courseState.completed.length}" max="16"></progress></div><div class="lessonmeta"><span>${l.topic}</span><span>${l.minutes} דקות</span><span>${l.kind==='lab'?'תרגול חי':'לימוד מושגי'}</span></div><h2 class="coursetitle">${l.title}</h2><div class="coursetabs"><button data-course-tab="overview" class="${courseTab==='overview'?'active':''}">הסבר</button><button data-course-tab="pins" class="${courseTab==='pins'?'active':''}">הדקים</button><button data-course-tab="practice" class="${courseTab==='practice'?'active':''}">תרגול</button></div><div id="coursecontent"></div><div class="coursebottom"><button id="prevlesson" ${courseState.current===0?'disabled':''}>הקודם</button><button id="completelesson" class="run">${done?'הושלם ✓':'בדיקה וסיום'}</button><button id="nextlesson" ${courseState.current===15?'disabled':''}>הבא</button></div>`;const content=$('coursecontent');if(courseTab==='overview'){content.innerHTML=`<p class="lessonintro">${l.intro}</p><div class="lessonwhy"><b>מה חשוב להבין?</b><p>${l.why}</p></div><h3>בסיום תוכלו</h3><ul>${l.goals.map(g=>`<li>${g}</li>`).join('')}</ul><button class="wide" id="gopractice">פתיחת התרגול</button>`;$('gopractice').onclick=()=>{courseTab='practice';renderCourse()}}else if(courseTab==='pins'){const n=nodes.find(n=>n.id===selected)||board(),c=n&&catalog.find(c=>c.type===n.type);content.innerHTML=c?`<p>הדקי ${c.name} במודל הלימודי. בדקו pinout רשמי לפני חיווט פיזי.</p><div class="coursepins">${c.pins.map((p,i)=>`<button data-lesson-pin="${i}"><b>${p}</b><span>${/GND|VSS/.test(p)?'ייחוס / אדמה':/VCC|5V|3V3|VDD/.test(p)?'הזנה':/^A\d/.test(p)?'כניסה אנלוגית בפרופיל':'אות / פונקציה לפי הרכיב'}</span></button>`).join('')}</div>`:'<p>הוסיפו רכיב ובחרו אותו כדי לחקור את ההדקים.</p>';document.querySelectorAll('[data-lesson-pin]').forEach(b=>b.onclick=()=>{select(n.id);connectPin(n.id,+b.dataset.lessonPin)})}else{content.innerHTML=`<ol class="lessonsteps">${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol>${l.preset?'<button class="wide" id="loadlesson">טעינת המעגל והקוד לתרגול</button>':'<p class="visualnotice">זהו שיעור מושגי. הפרוטוקול או התנהגות הרכיב אינם מדומים בגרסה הנוכחית.</p>'}${lessonInputControls()}<div class="checkpoint"><b>המשימה שלכם</b><p>${l.task}</p>${l.kind==='lab'?'<button id="verifypractice">בדיקת המשימה</button><p id="practiceresult"></p>':''}</div><h3>${l.question}</h3><div class="quizanswers">${l.answers.map((a,i)=>`<button data-answer="${i}" class="${answer===i?(i===l.correct?'correct':'incorrect'):''}">${a}</button>`).join('')}</div><p class="quizfeedback">${answer===undefined?'בחרו תשובה ובדקו את ההבנה.':answer===l.correct?l.explain:'עדיין לא. חזרו להסבר ונסו לבחור שוב.'}</p>`;document.querySelectorAll('[data-lesson-input]').forEach(input=>input.oninput=()=>{const n=nodes.find(n=>n.id===+input.dataset.lessonInput);if(!n)return;n.value=+input.value;document.getElementById('lessonvalue_'+n.id).textContent=n.value;update()});if($('loadlesson'))$('loadlesson').onclick=()=>loadLessonProject(l);if($('verifypractice'))$('verifypractice').onclick=()=>{practicePassed=!!l.check?.();$('practiceresult').textContent=practicePassed?'✓ המשימה עברה לפי מצב המעגל והמדידות.':'עדיין חסר חלק מהתרגול. בדקו את החיבורים, הערכים וההרצה.'};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{courseState.answers[l.id]=+b.dataset.answer;persistCourse();renderCourse()})}document.querySelectorAll('[data-course-tab]').forEach(b=>b.onclick=()=>{courseTab=b.dataset.courseTab;renderCourse()});$('prevlesson').onclick=()=>startLesson(courseState.current-1);$('nextlesson').onclick=()=>startLesson(courseState.current+1);$('completelesson').onclick=()=>{if(done)return toast('השיעור כבר הושלם');if(courseState.answers[l.id]!==l.correct){courseTab='practice';renderCourse();return toast('ענו נכון על שאלת ההבנה כדי להשלים')}if(l.kind==='lab'&&!practicePassed&&!l.check?.()){courseTab='practice';renderCourse();return toast('השלימו את המשימה במעבדה לפני הסיום')}courseState.completed.push(l.id);persistCourse();renderCourse();toast('השיעור הושלם וההתקדמות נשמרה')};lessonStrip.innerHTML='<div class="stripheading"><b>המסלול שלכם</b><span>16 שיעורים · הסבר, הדקים והתנסות</span><button id="alllessons">כל השיעורים</button></div><div class="lessonrail">'+lessons.map((x,i)=>`<button data-lesson="${i}" class="${i===courseState.current?'active':''}"><small>${courseState.completed.includes(x.id)?'✓ הושלם':x.topic}</small><b>${i+1}. ${x.title}</b><span>${x.minutes} דקות</span></button>`).join('')+'</div>';document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>startLesson(+b.dataset.lesson));$('alllessons').onclick=()=>showModal('<h1>מסלול יסודות האלקטרוניקה</h1><div class="modalgrid">'+lessons.map((x,i)=>`<button class="modalcard" onclick="startLesson(${i});document.getElementById('modal').close()"><h3>${i+1}. ${x.title}</h3><p>${x.topic} · ${x.minutes} דקות · ${x.kind==='lab'?'תרגול חי':'שיעור מושגי'}</p></button>`).join('')+'</div>')}
function loadLessonProject(lesson){const setup=()=>{if(lesson.preset==='motor')template('motor');else if(lesson.preset==='light')template('light');else if(lesson.preset==='analog')sensorTemplate();else if(['pwm','button'].includes(lesson.preset))loadControlProject(lesson.preset);else boardTemplate('arduino_0');document.body.dataset.workspace='learn';document.querySelectorAll('[data-workspace]').forEach(b=>b.classList.toggle('active',b.dataset.workspace==='learn'));lessonStart=performance.now();scopeSamples=[];practicePassed=false;renderCourse();rememberAction()};showModal('<h1>פתיחת תרגול</h1><p>התרגול יחליף את המעגל הפתוח. אפשר לשמור אותו תחילה או לחזור אליו באמצעות ביטול פעולה.</p><button id="confirmloadlesson" class="run">פתיחת התרגול</button>');$('confirmloadlesson').onclick=()=>{rememberAction();$('modal').close();setup()}}
function loadControlProject(kind){stopCode();nodes=[];wires=[];idseq=0;const b=addNode('arduino_0',-2,0),r=addNode('resistor',.7,-1),led=addNode('led',2.5,.8),sensor=addNode(kind==='button'?'button':'pot',1,1.6);const c=catalog.find(c=>c.type===b.type);activeBoard=b.id;const input=kind==='button'?0:c.pins.indexOf('A0');wires=[[{id:b.id,pin:1},{id:r.id,pin:0}],[{id:r.id,pin:1},{id:led.id,pin:0}],[{id:led.id,pin:1},{id:b.id,pin:c.pins.length-1}],[{id:b.id,pin:input},{id:sensor.id,pin:1}],[{id:b.id,pin:c.pins.length-2},{id:sensor.id,pin:0}],[{id:b.id,pin:c.pins.length-1},{id:sensor.id,pin:2}]];b.code=kind==='button'?'void setup() {\n  pinMode(3, OUTPUT);\n  pinMode(2, INPUT);\n}\nvoid loop() {\n  if (digitalRead(2) == HIGH) {\n    digitalWrite(3, HIGH);\n  } else {\n    digitalWrite(3, LOW);\n  }\n  delay(30);\n}':'void setup() {\n  pinMode(3, OUTPUT);\n  pinMode(A0, INPUT);\n  Serial.begin(9600);\n}\nvoid loop() {\n  int inputValue = analogRead(A0);\n  int brightness = map(inputValue, 0, 1023, 0, 255);\n  analogWrite(3, brightness);\n  Serial.println(brightness);\n  delay(100);\n}';$('projecttitle').textContent=kind==='button'?'לחצן שולט ב־LED':'עוצמת אור משתנה';select(sensor.id);running=false;update();mobilePanel('workspace');openCode(false)}
const existingTemplates=$('templates').onclick;$('templates').onclick=()=>{existingTemplates();const extra=document.createElement('div');extra.className='modalgrid';extra.innerHTML='<div class="modalcard"><h3>לחצן שמחליט</h3><p>תנאי if/else מפעיל LED לפי קלט דיגיטלי.</p><button onclick="loadControlProject(\'button\');document.getElementById(\'modal\').close()">פתיחת פרויקט</button></div><div class="modalcard"><h3>עוצמת אור משתנה</h3><p>פוטנציומטר, map ו־analogWrite במודל ממוצע.</p><button onclick="loadControlProject(\'pwm\');document.getElementById(\'modal\').close()">פתיחת פרויקט</button></div>';$('modalbody').append(extra)};renderCourse();

function lessonInputControls(){return '<div class="lessoncontrols">'+nodes.filter(n=>catalog.find(c=>c.type===n.type).input||n.type==='ldr'||n.type==='switch').map(n=>{const c=catalog.find(c=>c.type===n.type),max=digitalSensors.has(n.type)||n.type==='switch'?1:100;return `<label>${c.name}<b id="lessonvalue_${n.id}">${n.value}</b><input aria-label="קלט ${c.name}" type="range" min="0" max="${max}" value="${n.value}" data-lesson-input="${n.id}"></label>`}).join('')+'</div>'}
